        return self._constructor(np.nan, index=self._selected_obj.index)

    # Setting pairwise default behavior
    pairwise = True if pairwise is None else pairwise

    if len(self._selected_obj) != len(other):
        raise ValueError("Index length mismatch between both Series.")

    # Ensure that both Series are of a numeric type
    if not (self._selected_obj.select_dtypes(include='number').size and 
            other._selected_obj.select_dtypes(include='number').size):
