    # Check if the window is a valid frequency and not too large
    if isinstance(window, str) and window.endswith('H'):
        window = pd.to_timedelta(window)
    elif window > 1e12:  # Example limit to prevent MemoryError
        raise ValueError("Window size too large, please specify a smaller window.")

    def _get_corr(a, b):
        a = a.rolling(
            window=window, min_periods=self.min_periods, center=self.center
        )
        b = b.rolling(
            window=window, min_periods=self.min_periods, center=self.center
        )

        return a.cov(b, **kwargs) / (a.std(**kwargs) * b.std(**kwargs))

    return _flex_binary_moment(
        self._selected_obj, other._selected_obj, _get_corr, pairwise=bool(pairwise)
    )
