def corr(self, other=None, pairwise=None, **kwargs):
    if other is None:
        other = self._selected_obj

    # Check if either series is empty
    if self._selected_obj.empty or other.empty:
        return self._constructor([np.nan] * len(self._selected_obj), index=self._selected_obj.index)

    # Default pairwise to True if None
    pairwise = pairwise if pairwise is not None else True

    # Check if we're dealing with frequency-based rolling
    if not self.is_freq_type:
        raise ValueError("Rolling window must be time-based.")

    other = self._shallow_copy(other)
    window = self._get_window(other)

    def _get_corr(a, b):
        a_rolling = a.rolling(window=window, min_periods=self.min_periods, center=self.center)
        b_rolling = b.rolling(window=window, min_periods=self.min_periods, center=self.center)

        return a_rolling.cov(b_rolling, **kwargs) / (a_rolling.std(**kwargs) * b_rolling.std(**kwargs))

    return _flex_binary_moment(
        self._selected_obj, other._selected_obj, _get_corr, pairwise=bool(pairwise)
    )
